// releases through CDefBase::Release (`dec [ecx+4] ; jne ; call [eax+4]`) and nulls the field (`and [edi],0`, kept in the size TU);
// pragma optimize("s", on).
#pragma optimize("s", on)

struct CDefVirtual {
    virtual void v00();
    virtual void Destroy();                // slot 1
};
struct CDefBase : CDefVirtual {
    long m_count;                          // +4
    void Release()
